#!/usr/bin/env python3
"""Generate trilingual lessons 5–10 for the first Informatics release block."""
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/"course/lessons/informatics"
L=("ru","kz","en")
def t(ru,kz,en): return dict(zip(L,(ru,kz,en)))

H={
"ru":t("Где мы на карте","Картадағы орнымыз","Where we are on the map"),
}
HEAD={
"ru":("Лид (summary)","Где мы на карте","Жизненный образ и точная модель","Граница образа","Опорный сигнал","Разобранный пример","Предскажите до наблюдения","Воспроизведите без подсказки","Найдите и исправьте ошибку","Перенос в новую ситуацию","Изменение проекта","Задание","Возврат через 1, 7 и 30 дней","Обязательное","На своих данных","По желанию","Следующий урок"),
"kz":("Лид (summary)","Картадағы орнымыз","Өмірдегі бейне және нақты модель","Ұқсатудың шекарасы","Сабақтың тірек сигналы","Талданған мысал","Алдымен болжаңыз","Көмексіз жаңғыртыңыз","Қатені тауып түзетіңіз","Жаңа жағдайға көшіру","Жобаға енгізілетін өзгеріс","Тапсырма","1, 7 және 30 күннен кейін қайталау","Міндетті","Өз дерегіңізбен","Қалауыңызша","Келесі сабақ"),
"en":("Lead (summary)","Where we are on the map","A familiar image and the precise model","The limit of the analogy","The lesson's support signal","Worked example","Predict before observing","Recall without a prompt","Find and correct the mistake","Transfer to a new setting","Project change","Exercise","Retrieval after 1, 7, and 30 days","Required","With your own data","Optional","Next lesson")}

ROWS=[
(5,"cpu-memory-storage","map-05-memory",t("Процессор, оперативная память и хранилище","Процессор, жедел жад және сақтау құрылғысы","Processor, working memory, and storage"),t("Различим исполнение, временное состояние и постоянное сохранение, а затем определим, что обязан хранить помощник.","Орындауды, уақытша күйді және тұрақты сақтауды ажыратып, көмекші нені сақтауы керегін анықтаймыз.","We separate execution, temporary state, and persistent storage, then decide what the assistant must keep."),t("Редактируемая заметка мгновенно меняется, но после отключения несохранённая часть может исчезнуть. Процессор выполняет инструкции. ОЗУ держит код и текущее состояние работающего процесса. Постоянное хранилище удерживает файлы без питания. Кэш ускоряет доступ, но не заменяет сохранение. Скорость зависит от всей цепочки, а не от одного большого числа.","Өңделіп жатқан жазба бірден өзгереді, бірақ қуат өшсе, сақталмаған бөлігі жоғалады. Процессор нұсқауды орындайды. Жедел жад жұмыс процесінің коды мен күйін ұстайды. Тұрақты сақтау құрылғысы файлды қуатсыз да сақтайды. Кэш қолжетімділікті жылдамдатады, бірақ сақтауды алмастырмайды.","An edited note changes immediately, but an unsaved part may vanish after power loss. The processor executes instructions. RAM holds code and current process state. Persistent storage keeps files without power. Cache speeds access but does not replace saving."),"storage → RAM ↔ processor → save → storage",t("`tasks.json` накопитель читает в ОЗУ; программа разбирает данные; изменение живёт в ОЗУ; сохранение записывает новую версию. Видимый экран ещё не доказывает сохранение.","`tasks.json` жинақтауыштан жедел жадқа оқылады; бағдарлама деректі талдайды; өзгеріс жедел жадта тұрады; сақтау жаңа нұсқаны жазады. Экрандағы көрініс сақтауды дәлелдемейді.","`tasks.json` is read from storage into RAM; software parses it; a change lives in RAM; saving writes a new version. A visible screen does not prove persistence."),t("«256 ГБ памяти гарантируют скорость». Здесь смешаны хранилище, ОЗУ и быстродействие. Назовите измеренное узкое место.","«256 ГБ жад жылдамдыққа кепіл». Мұнда сақтау, жедел жад және өнімділік араласқан. Өлшенген тар орынды атаңыз.","“256 GB of memory guarantees speed.” This mixes storage, RAM, and performance. Name the measured bottleneck."),t("Зафиксируйте состояния: черновик в ОЗУ, сохранённая запись и результат после повторного запуска. Подтверждайте сохранение после записи и повторного чтения.","Күйлерді бекітіңіз: жедел жадтағы шимай, сақталған жазба және қайта іске қосқандағы нәтиже. Сақтауды жазу мен қайта оқудан кейін растаңыз.","Define a draft in RAM, a saved record, and the result after restart. Confirm saving after write and read-back."),t("операционная система, процесс и приложение","операциялық жүйе, процесс және қолданба","operating system, process, and application")),
(6,"os-process-app","map-06-os-process",t("Операционная система, процесс и приложение","Операциялық жүйе, процесс және қолданба","Operating system, process, and application"),t("Разделим файл программы, работающий процесс и услуги операционной системы, чтобы понимать запуск, разрешения и ошибки.","Бағдарлама файлын, жұмыс процесін және операциялық жүйе қызметін ажыратып, іске қосу, рұқсат пен қатені түсінеміз.","We separate a program file, a running process, and OS services to understand launch, permissions, and errors."),t("Иконка ссылается на файл программы. При запуске ОС выделяет память, создаёт процесс и связывает его с файлами и устройствами. ОС управляет процессами, памятью, файлами, устройствами и доступом. Драйвер связывает общую команду ОС с оборудованием. Разрешение ограничивает действие, но не доказывает безопасность приложения.","Белгіше бағдарлама файлына сілтейді. Іске қосқанда ОЖ жад бөліп, процесс жасап, файл және құрылғымен байланыстырады. ОЖ процесс, жад, файл, құрылғы және қолжетімділікті басқарады. Драйвер жалпы пәрменді жабдықпен байланыстырады. Рұқсат қауіпсіздікті дәлелдемейді.","An icon refers to a program file. At launch, the OS allocates memory, creates a process, and connects it to files and devices. The OS manages processes, memory, files, devices, and access. A driver links a general OS command to hardware. Permission does not prove safety."),"program file → OS → process → resource → result",t("Открывая файл, ОС проверяет путь и право, выбирает приложение, создаёт процесс и передаёт ему файл. Ошибка должна называть первое неудавшееся действие.","Файл ашқанда ОЖ жол мен құқықты тексеріп, қолданбаны таңдап, процесс жасап, файлды береді. Қате алғашқы сәтсіз әрекетті атауы керек.","When opening a file, the OS checks its path and access, chooses an app, creates a process, and passes the file. An error should name the first failed action."),t("«Дайте все разрешения, чтобы не было ошибок». Это скрывает причину и увеличивает возможный ущерб. Требуйте минимальное право.","«Қате болмасын деп барлық рұқсатты берейік». Бұл себепті жасырып, ықтимал зиянды арттырады. Ең аз құқықты сұраңыз.","“Grant every permission so errors stop.” This hides the cause and increases possible harm. Require least privilege."),t("Перечислите ресурсы процесса: файл данных, экран и клавиатура. Для каждого укажите минимальное право и понятный отказ. Камера, сеть и геолокация не нужны.","Процесс ресурсын атаңыз: дерек файлы, экран, пернетақта. Әрқайсысына ең аз құқық пен түсінікті бас тарту жазыңыз. Камера, желі және орын қажет емес.","List process resources: data file, display, and keyboard. Give each least privilege and a clear denial. Camera, network, and location are unnecessary."),t("файлы, папки и точный адрес","файлдар, бумалар және нақты мекенжай","files, folders, and exact paths")),
(7,"files-folders-paths","map-07-paths",t("Файлы, папки и точный адрес","Файлдар, бумалар және нақты мекенжай","Files, folders, and exact paths"),t("Построим дерево проекта и отличим имя от пути, относительный адрес от абсолютного и отсутствие файла от неверного места поиска.","Жоба ағашын құрып, атауды жолдан, салыстырмалы мекенжайды абсолюттіден және жоқ файлды қате іздеу орнынан ажыратамыз.","We build a project tree and distinguish a name from a path, a relative path from an absolute one, and a missing file from a wrong search location."),t("Два файла могут называться `plan.txt`. Файл — именованная последовательность данных; папка связывает имена; путь перечисляет переходы. Абсолютный путь начинается от корня, относительный — от рабочей папки. Расширение сообщает ожидаемый формат, но переименование `.txt` в `.jpg` не превращает текст в фотографию.","Екі файл `plan.txt` деп атала алады. Файл — атаулы дерек тізбегі, бума атауларды байланыстырады, жол өтулерді көрсетеді. Абсолют жол түбірден, салыстырмалы жол жұмыс бумасынан басталады. `.txt` атауын `.jpg` ету мәтінді фотоға айналдырмайды.","Two files may be named `plan.txt`. A file is a named data sequence; a folder maps names; a path lists transitions. An absolute path begins at a root and a relative path at the working folder. Renaming `.txt` to `.jpg` does not turn text into a photo."),"assistant/ → data/tasks.json | docs/passport.md | tests/",t("Из `assistant` путь `data/tasks.json` однозначен. `../tasks.json` сначала поднимается к родителю и может указать другой файл. Перед исправлением проверяют рабочую папку и вычисленный путь.","`assistant` ішінен `data/tasks.json` бірмәнді. `../tasks.json` ата-анаға көтеріліп, басқа файлды көрсетуі мүмкін. Түзетер алдында жұмыс бумасы мен есептелген жолды тексеріңіз.","From `assistant`, `data/tasks.json` is unambiguous. `../tasks.json` first moves to the parent and may identify another file. Inspect the working folder and resolved path before fixing."),t("«Файл не найден, значит его нет». Возможно, программа ищет не там или имя отличается одним символом. Разделите наблюдение и причины.","«Файл табылмады, демек жоқ». Бағдарлама басқа жерден іздеуі немесе атауда бір таңба айырмасы болуы мүмкін. Бақылау мен себепті ажыратыңыз.","“File not found means no file exists.” The program may look elsewhere or the name may differ by one character. Separate observation from causes."),t("Создайте `assistant/data`, `assistant/docs`, `assistant/tests`. Паспорт храните в `docs`, три вымышленные записи — в `data`. Зафиксируйте рабочую папку.","`assistant/data`, `assistant/docs`, `assistant/tests` жасаңыз. Паспорт `docs`, үш ойдан шығарылған жазба `data` ішінде болсын. Жұмыс бумасын бекітіңіз.","Create `assistant/data`, `assistant/docs`, and `assistant/tests`. Keep the passport in `docs`, three fictional records in `data`, and record the working folder."),t("формат, программа и разрешение автора","пішім, бағдарлама және автор рұқсаты","formats, software, and the creator's permission")),
(8,"formats-software-licenses","map-08-formats",t("Формат, программа и разрешение автора","Пішім, бағдарлама және автор рұқсаты","Formats, software, and the creator's permission"),t("Отделим байты от правил чтения, выберем открытый формат и проверим лицензию до добавления чужого материала.","Байтты оқу ережесінен ажыратып, ашық пішім таңдап, бөтен материалды қоспай тұрып лицензияны тексереміз.","We separate bytes from reading rules, choose an open format, and check a licence before adding someone else's material."),t("Формат определяет расположение и смысл данных. Кодировка связывает числа с символами. MIME-тип описывает вид содержимого при обмене. Лицензия сообщает разрешённое использование; отсутствие лицензии не означает свободу. Доступ к файлу не даёт права копировать его, а расширение само по себе не меняет байты.","Пішім деректің орналасуы мен мағынасын анықтайды. Кодтау санды таңбамен байланыстырады. MIME мазмұн түрін сипаттайды. Лицензия рұқсатты айтады; лицензияның жоқтығы еркіндік емес. Файлға қолжетімділік көшіруге құқық бермейді.","A format defines data layout and meaning. An encoding maps numbers to characters. A MIME type describes exchanged content. A licence states permitted use; no licence does not mean freedom. Access to a file does not grant copying rights, and an extension does not change bytes."),"bytes + format + encoding → data | source + licence + attribution → permitted use",t("Для записей выбираем UTF-8 JSON с полями `id`, `title`, `date`, `state`, `category`. Валидный JSON ещё не гарантирует правильные даты и обязательные поля — их проверяет наша схема.","Жазбаға `id`, `title`, `date`, `state`, `category` өрістері бар UTF-8 JSON таңдаймыз. Дұрыс JSON күн мен міндетті өрістің дұрыстығын кепілдемейді — оны сұлба тексереді.","We choose UTF-8 JSON with `id`, `title`, `date`, `state`, and `category`. Valid JSON does not guarantee valid dates or required fields; our schema checks them."),t("«Найденную в поиске картинку можно брать». Найдите первоисточник, автора, лицензию, дату и условия конкретного использования.","«Іздеуден табылған суретті ала беруге болады». Түпнұсқа, автор, лицензия, күн және қолдану шартын табыңыз.","“A search-result image is free to take.” Find the original source, creator, licence, date, and terms for the intended use."),t("Зафиксируйте JSON-схему. Для внешнего материала ведите источник, автора, лицензию и дату проверки. Первой версии внешние материалы не обязательны.","JSON сұлбасын бекітіңіз. Сыртқы материалға дереккөз, автор, лицензия және тексеру күнін жазыңыз. Алғашқы нұсқаға сыртқы материал міндетті емес.","Fix the JSON schema. For external material, record source, creator, licence, and check date. External material is optional in the first release."),t("версии, совместная работа и доступность","нұсқалар, бірлескен жұмыс және қолжетімділік","versions, collaboration, and accessibility")),
(9,"versions-collaboration-accessibility","map-09-versions",t("Версии, совместная работа и доступность","Нұсқалар, бірлескен жұмыс және қолжетімділік","Versions, collaboration, and accessibility"),t("Сохраним осмысленную историю, объединим изменения без перезаписи чужой работы и проверим доступность интерфейса.","Мағыналы тарихты сақтап, бөтен жұмысты баспай өзгерісті біріктіріп, интерфейс қолжетімділігін тексереміз.","We preserve meaningful history, combine changes without overwriting another person's work, and test accessibility."),t("Файлы `final2-new` не объясняют происхождение. Версия — определённое состояние продукта. Малое изменение имеет причину и проверку. Сравнение показывает отличие, возврат восстанавливает известное состояние, слияние соединяет независимые правки. Доступность требует восприятия и управления разными способами: текст не заменяется цветом, клавиатура достигает действий, ошибка понятна.","`final2-new` файлдары шығу тегін түсіндірмейді. Нұсқа — өнімнің белгілі күйі. Шағын өзгерістің себебі мен тексеруі бар. Салыстыру айырманы, қайтару белгілі күйді, біріктіру тәуелсіз түзетуді қосады. Қолжетімділік мәтінді тек түспен бермеуді, пернетақта әрекетін және түсінікті қатені талап етеді.","Files named `final2-new` do not explain ancestry. A version is a defined product state. A small change has a reason and check. Comparison shows differences, revert restores known state, and merge combines independent edits. Accessibility requires more than colour, keyboard reachability, and clear errors."),"small change → compare → review → test → version → recover",t("Изменение «запретить пустой заголовок» содержит одно правило, пример ошибки и проверку. Его не смешивают с новым цветом и переименованием папок, поэтому причину легко проверить и отменить.","«Бос атауға тыйым салу» өзгерісінде бір ереже, қате мысалы және тексеру бар. Ол түс пен бума атауын өзгертумен араласпайды, сондықтан тексеру және қайтару оңай.","The change “reject an empty title” contains one rule, an error example, and a check. It is not mixed with colour or folder renaming, so it is easy to verify and reverse."),t("«Доступность добавим в конце». Позднее исправление структуры дороже. Проверьте контраст, заголовки, клавиатуру, фокус и сообщения уже сейчас.","«Қолжетімділікті соңында қосамыз». Құрылымды кеш түзету қымбат. Контраст, тақырып, пернетақта, фокус және хабарды қазір тексеріңіз.","“We will add accessibility at the end.” Late structural repair costs more. Test contrast, headings, keyboard, focus, and messages now."),t("Начните журнал решений и снимок `v0.1-foundations`. Проверьте паспорт без цвета и только клавиатурой. Запишите одну помеху и исправление.","Шешім журналын және `v0.1-foundations` суретін бастаңыз. Паспортты түссіз және тек пернетақтамен тексеріңіз. Бір кедергі мен түзетуді жазыңыз.","Start a decision log and snapshot `v0.1-foundations`. Test the passport without colour and with keyboard only. Record one barrier and repair."),t("контрольная точка первого блока","бірінші бөлімнің бақылау нүктесі","the first-block mastery checkpoint")),
(10,"systems-mastery","map-10-mastery",t("Контрольная точка: рабочее место проекта","Бақылау нүктесі: жобаның жұмыс ортасы","Mastery checkpoint: the project workspace"),t("Соберём версию 0.1, проверим десять навыков сейчас и через семь дней и докажем перенос на новом устройстве.","0.1 нұсқасын жинап, он дағдыны қазір және жеті күннен кейін тексеріп, жаңа құрылғыда көшіруді дәлелдейміз.","We assemble version 0.1, check ten skills now and after seven days, and prove transfer on a new device."),t("Просмотр страниц создаёт знакомство, но не доказывает воспроизведение. Блок освоен при 8 из 10 сейчас, включая перенос, и 7 из 10 через семь дней. Ошибка указывает связь для восстановления, а число попыток не ограничивается. Проект тоже является доказательством: другой человек должен найти данные и объяснить структуру по README.","Беттерді көру таныстық береді, бірақ жаңғыртуды дәлелдемейді. Бөлім қазір көшірумен бірге 10-нан 8 және жеті күннен кейін 10-нан 7 орындалса меңгерілді. Қате қалпына келетін байланысты көрсетеді, әрекет саны шектелмейді. Басқа адам README арқылы деректі тауып, құрылымды түсіндіруі керек.","Viewing pages creates familiarity but does not prove recall. Mastery requires 8 of 10 now including transfer, and 7 of 10 after seven days. An error identifies the link to rebuild, and attempts are unlimited. Project evidence also matters: another person must locate data and explain its structure from the README."),"explain → model → diagnose → transfer → project evidence → 8/10 now → 7/10 later",t("Экран показывает три записи. Этого недостаточно: проверяются повторный запуск, неверный путь, пустой ввод, минимальные разрешения, история решения и объяснение системы. Каждый успешный шаг оставляет наблюдаемое доказательство.","Экран үш жазба көрсетті. Бұл жеткіліксіз: қайта іске қосу, қате жол, бос кіріс, ең аз рұқсат, шешім тарихы және жүйе түсіндірмесі тексеріледі. Әр сәтті қадам бақыланатын дәлел қалдырады.","The display shows three records. That is insufficient: test restart, wrong path, empty input, least permissions, decision history, and a system explanation. Every success leaves observable evidence."),t("«Я получил восемь ответов, значит закончил». Укажите объяснение, перенос, проверенный артефакт и дату отсроченной попытки.","«Сегіз жауап алдым, демек бітті». Түсіндіру, көшіру, тексерілген артефакт және кейінгі әрекет күнін көрсетіңіз.","“I got eight answers, so I am done.” Identify explanation, transfer, a checked artefact, and the delayed attempt date."),t("Версия 0.1 содержит паспорт, три вымышленные записи, дерево папок, договоры ввода-вывода, таблицу устройства, реестр источников, журнал решений и README. Защитите одно исправленное заблуждение.","0.1 нұсқасында паспорт, үш ойдан шығарылған жазба, бума ағашы, кіріс-шығыс шарты, құрылғы кестесі, дереккөз тізімі, шешім журналы және README бар. Бір түзетілген жаңсақ ойды қорғаңыз.","Version 0.1 contains a passport, three fictional records, folder tree, input-output contracts, device table, source register, decision log, and README. Defend one corrected misconception."),t("бит: два различимых состояния","бит: ажыратылатын екі күй","the bit: two distinguishable states")),
]

COMMON={
"ru":("Рабочий образ помогает войти в тему, но не заменяет механизм. Назовите место, где сравнение перестаёт быть точным.","Закройте страницу, восстановите сигнал и объясните каждый переход на новом примере.","Примените модель к устройству или файлу, которого не было в уроке. Отделите наблюдение от предположения.","Выполните пример, исправьте ошибку и внесите изменение в проект с причиной.","Проверьте решение на трёх вымышленных записях.","Попросите другого человека восстановить объяснение по схеме.","Завтра восстановите сигнал; через семь дней решите равноценную задачу; через тридцать дней проверьте решение в проекте."),
"kz":("Өмірлік бейне тақырыпқа кіргізеді, бірақ механизмді алмастырмайды. Ұқсату дәл болмайтын жерді атаңыз.","Бетті жауып, сигналды қалпына келтіріп, әр өтуді жаңа мысалмен түсіндіріңіз.","Модельді сабақта болмаған құрылғы не файлға қолданыңыз. Бақылауды болжамнан ажыратыңыз.","Мысалды орындап, қатені түзетіп, себебімен жобаға өзгеріс енгізіңіз.","Шешімді үш ойдан шығарылған жазбада тексеріңіз.","Басқа адамнан сұлба бойынша түсіндіруді қалпына келтіруді сұраңыз.","Ертең сигналды қалпына келтіріңіз; жеті күннен кейін баламалы тапсырма орындаңыз; отыз күннен кейін шешімді жобада тексеріңіз."),
"en":("The familiar image opens the topic but does not replace the mechanism. State where the analogy stops being accurate.","Hide the page, rebuild the signal, and explain every transition with a new example.","Apply the model to a device or file absent from the lesson. Separate observation from assumption.","Complete the example, correct the error, and make the project change with a reason.","Test the decision on three fictional records.","Ask another person to rebuild the explanation from the map.","Rebuild the signal tomorrow; solve an equivalent task after seven days; after thirty days, verify the decision in the project.")}

EXT={
"ru":(
"Начните не с определения, а с наблюдения. Откройте на своём устройстве объект, связанный с темой урока, и запишите, что вы действительно видите: имя, место, действие и результат. Рядом отдельно запишите своё объяснение причины. Такое разделение не позволяет принять догадку за факт. После опыта сверьте объяснение с точной моделью и исправьте только ту связь, которая оказалась неверной.",
"До опыта закройте продолжение и письменно предскажите результат. Укажите не только ответ, но и цепочку причин по опорному сигналу. Затем выполните действие, зафиксируйте наблюдение и сравните его с прогнозом. Совпадение без объяснения считается удачей, а не пониманием; расхождение становится полезной подсказкой о том, какую связь надо восстановить.",
"Объясните тему человеку, который не читал урок. Не употребляйте новый термин, пока не раскроете его простыми словами. Затем верните точное название и покажите его место в системе. Слушатель должен суметь предсказать следующий шаг и привести другой пример. Если он только повторяет формулировку, сократите объяснение до опорного сигнала и соберите его заново.",
"В журнале решения оставьте четыре строки: что хотели получить, что наблюдали, почему выбрали это действие и как проверили результат. Снимок экрана может дополнять проверку, но не заменяет текст и рабочий файл. Личные данные не используйте: три вымышленные записи дают такую же проверяемость и позволяют безопасно показать проект другому человеку.",
"Критерий готовности: вы воспроизводите сигнал без страницы, исправляете предложенную ошибку, переносите модель на незнакомый пример и показываете изменение проекта. Если один пункт не получается, вернитесь к соответствующей связи, а не перечитывайте весь урок. После исправления повторите только равноценную задачу с другими данными."
),
"kz":(
"Анықтамадан емес, бақылаудан бастаңыз. Құрылғыңыздан сабақ тақырыбына қатысты нысанды ашып, шынымен көргеніңізді жазыңыз: атауы, орны, әрекеті және нәтижесі. Себеп туралы түсіндірмеңізді бөлек белгілеңіз. Осылайша жорамал дерек ретінде қабылданбайды. Тәжірибеден кейін түсіндірмені дәл модельмен салыстырып, қате болған байланысты ғана түзетіңіз.",
"Тәжірибеге дейін жалғасын жауып, нәтижені жазбаша болжаңыз. Жауаппен бірге тірек сигналындағы себептер тізбегін көрсетіңіз. Содан кейін әрекетті орындап, бақылауды тіркеп, болжаммен салыстырыңыз. Түсіндірмесіз сәйкестік түсіну емес, сәттілік саналады; айырмашылық қай байланысты қалпына келтіру керегін көрсетеді.",
"Тақырыпты сабақты оқымаған адамға түсіндіріңіз. Жаңа терминді қарапайым сөзбен ашпайынша қолданбаңыз. Кейін дәл атауын қайтарып, жүйедегі орнын көрсетіңіз. Тыңдаушы келесі қадамды болжап, өзге мысал келтіре алуы керек. Егер ол тек сөйлемді қайталаса, түсіндірмені тірек сигналға дейін қысқартып, қайта құрыңыз.",
"Шешім журналына төрт жол қалдырыңыз: не алғыңыз келді, нені байқадыңыз, бұл әрекетті неге таңдадыңыз және нәтижені қалай тексердіңіз. Экран суреті тексеруді толықтыра алады, бірақ мәтін мен жұмыс файлын алмастырмайды. Жеке дерек қолданбаңыз: үш ойдан шығарылған жазба да дәл сондай тексеріледі және жобаны қауіпсіз көрсетуге мүмкіндік береді.",
"Дайындық өлшемі: сигналды бетсіз жаңғыртасыз, ұсынылған қатені түзетесіз, модельді бейтаныс мысалға көшіресіз және жоба өзгерісін көрсетесіз. Бір тармақ орындалмаса, бүкіл сабақты қайта оқымай, тиісті байланысқа оралыңыз. Түзеткеннен кейін басқа дерекпен баламалы тапсырманы қайталаңыз."
),
"en":(
"Start with an observation rather than a definition. Open an object on your device that relates to the lesson and record only what you can see: its name, location, action, and result. Write your explanation of the cause separately. This prevents a guess from becoming a fact. After the experiment, compare the explanation with the precise model and repair only the link that was wrong.",
"Before the experiment, hide the continuation and predict the result in writing. Give the chain of causes from the support signal as well as the answer. Perform the action, record the observation, and compare it with the prediction. A match without an explanation is luck rather than understanding; a mismatch is useful evidence about the link that needs rebuilding.",
"Explain the topic to someone who has not read the lesson. Do not use a new term until you have unpacked it in plain words. Then restore its precise name and show its place in the system. The listener should be able to predict the next step and give a different example. If they merely repeat a sentence, reduce the explanation to the support signal and rebuild it.",
"Keep four lines in the decision log: the intended result, the observation, the reason for the chosen action, and the verification. A screenshot can support evidence but cannot replace text and the working file. Do not use personal data: three fictional records provide the same testability and let you show the project safely to another person.",
"The readiness criterion is concrete: reproduce the signal without the page, correct the proposed error, transfer the model to an unfamiliar example, and show the project change. If one part fails, return to that link instead of rereading the whole lesson. After repairing it, repeat only an equivalent task with different data."
)}

def render(row,lang):
 n,slug,mapname,title,summary,model,signal,example,error,project,nxt=row; h=HEAD[lang]; c=COMMON[lang]
 x=EXT[lang]
 parts=[f"# {title[lang]}",f"_{h[0]}:_ **{summary[lang]}**",f"## {h[1]}",summary[lang],x[0],f"![{title[lang]}](/static/course/informatics/{mapname}-{lang}.svg)",f"## {h[2]}",model[lang],f"## {h[3]}",c[0],f"## {h[4]}",f"`{signal}`",f"## {h[5]}",example[lang],f"## {h[6]}",x[1],f"## {h[7]}",c[1],x[2],f"## {h[8]}",error[lang],f"## {h[9]}",c[2],f"## {h[10]}",project[lang],x[3],f"## {h[11]}",f"**{h[13]}.** {c[3]}",f"**{h[14]}.** {c[4]}",f"**{h[15]}.** {c[5]}",x[4],f"## {h[12]}",c[6],f"[{h[16]}: {nxt[lang]}](/course/informatics?lang={lang})"]
 return "\n\n".join(parts)+"\n"

def main():
 OUT.mkdir(parents=True,exist_ok=True)
 for row in ROWS:
  for lang in L:
   suffix="" if lang=="ru" else f"-{lang}"
   (OUT/f"{row[0]:02d}-{row[1]}{suffix}.md").write_text(render(row,lang),encoding="utf-8")
 print("Generated 18 localized foundation lesson pages")

if __name__=="__main__": main()
